actions.script:
created = false
const workEffort = ec.entity.find('mantle.work.effort.WorkEffort').condition('workEffortId', workEffortId).one()
if (workEffort == null) { ec.message.addError(`Work effort ${workEffortId} not found`); return }
const info = ec.service.sync().name('mantle.party.CommunicationServices.get#RecordLinkInfo')
        .parameters({recordEntityName: recordEntityName, recordId: recordId}).call()
if (ec.message.hasError()) return
recordEntityName = info.recordEntityName

let keys
if (info.workEffortJoin) {
    linkEntityName = info.workEffortJoin.entityName
    keys = {workEffortId: workEffortId, [info.workEffortJoin.keyField]: recordId}
} else {
    linkEntityName = 'mantle.work.effort.WorkEffortRecord'
    keys = {workEffortId: workEffortId, recordEntityName: recordEntityName, recordId: recordId}
}
if (ec.entity.find(linkEntityName).condition(keys).one() != null) return
const fields = info.workEffortJoin ? keys : Object.assign({linkedByUserId: ec.user.userId, linkedDate: ec.user.nowTimestamp}, keys)
ec.service.sync().name('create#' + linkEntityName).parameters(fields).call()
if (ec.message.hasError()) return
created = true

if (notifyFollowers) ec.service.sync().name('mantle.party.CommunicationServices.notify#RecordFollowers').parameters({
    recordEntityName: recordEntityName, recordId: recordId, kind: 'activities', workEffortId: workEffortId,
    subject: workEffort.workEffortName, body: workEffort.description, recordUrl: recordUrl}).call()

unlinked = false
const info = ec.service.sync().name('mantle.party.CommunicationServices.get#RecordLinkInfo')
        .parameters({recordEntityName: recordEntityName, recordId: recordId}).call()
if (ec.message.hasError()) return
const removeRows = (entityName, keys) => {
    for (const row of ec.entity.find(entityName).condition(keys).list()) {
        ec.service.sync().name('delete#' + entityName).parameters(row.getPrimaryKeys()).call()
        if (ec.message.hasError()) return
        unlinked = true
    }
}
if (info.workEffortJoin) removeRows(info.workEffortJoin.entityName, {workEffortId: workEffortId, [info.workEffortJoin.keyField]: recordId})
removeRows('mantle.work.effort.WorkEffortRecord', {workEffortId: workEffortId, recordEntityName: info.recordEntityName, recordId: recordId})

overdue = []
dueToday = []
laterToday = []
sourceGroups = []
failedSources = []
approvalCount = 0
const cf = ec.entity.conditionFactory
const builtInService = 'mantle.work.WorkEffortServices.get#UserTodayItems'
const toMillis = (value) => {
    if (value == null || value === '') return null
    if (typeof value === 'number') return value
    if (value instanceof Date) return value.getTime()
    const text = String(value)
    if (/^-?\d+$/.test(text)) return Number(text)
    const parsed = Date.parse(text)
    return Number.isNaN(parsed) ? null : parsed
}
const asDate = (millis) => millis == null ? null : new Date(millis)
const messageOf = (err) => String(err && err.message ? err.message : err)
// run a part on its own: its errors (thrown or in ec.message) come back as the message, the caller's stay
const attempt = (run) => {
    ec.message.pushErrors()
    try {
        const out = run()
        if (ec.message.hasError()) return {ok: false, message: ec.message.getErrorsString()}
        return {ok: true, out: out}
    } catch (err) {
        return {ok: false, message: messageOf(err)}
    } finally {
        ec.message.clearErrors()
        ec.message.popErrors()
    }
}

// the user and party: the current user's; another's only for internal work
const currentUserId = ec.user.userId || null
const currentPartyId = ec.user.userAccount?.partyId || null
if (!userId && !partyId) {
    userId = currentUserId
    partyId = currentPartyId
} else if (!partyId) {
    partyId = userId === currentUserId ? currentPartyId : (ec.entity.find('moqui.security.UserAccount')
            .condition('userId', userId).disableAuthz().one()?.partyId || null)
} else if (!userId) {
    userId = partyId === currentPartyId ? currentUserId : (Array.from(ec.entity.find('moqui.security.UserAccount')
            .condition('partyId', partyId).selectField('userId').disableAuthz().list())[0]?.userId || null)
}
if ((userId && userId !== currentUserId) || (partyId && partyId !== currentPartyId)) {
    const wasDisabled = ec.artifactExecution.disableAuthz()
    if (!wasDisabled) {
        ec.artifactExecution.enableAuthz()
        ec.message.addError("Another user's Today is read only with authorization disabled")
        return
    }
}
if (!partyId) return

// today in the session's time zone
const now = ec.user.nowTimestamp
const nowMillis = toMillis(now)
const dayText = (millis) => ec.l10n.format(String(millis), 'yyyy-MM-dd')
const dayStart = (text) => toMillis(ec.l10n.parseTimestamp(text + ' 00:00:00.000', 'yyyy-MM-dd HH:mm:ss.SSS'))
// a day is 23 to 25 hours, so 30 hours after its start is in the next one
const nextDayStart = (text) => dayStart(dayText(dayStart(text) + 30 * 3600000))
// a date field (allDayStart) has no time zone: it reaches a script as the epoch millis of its UTC midnight
const dayTextOf = (value) => {
    if (value == null || value === '') return null
    const text = String(value)
    if (/^\d{4}-\d{2}-\d{2}/.test(text)) return text.substring(0, 10)
    const millis = toMillis(value)
    return millis == null ? null : new Date(millis).toISOString().substring(0, 10)
}
const todayText = dayText(nowMillis)
const todayStartMillis = dayStart(todayText)
const tomorrowStartMillis = nextDayStart(todayText)
const todayStart = new Date(todayStartMillis)
const tomorrowStart = new Date(tomorrowStartMillis)
const todayDate = ec.l10n.parseDate(todayText, 'yyyy-MM-dd')

const kindOf = (workEffort) => {
    if (workEffort.workEffortTypeEnumId === 'WetEvent') return workEffort.purposeEnumId === 'WepMeeting' ? 'meeting' : 'event'
    return {WepPhoneCall: 'call', WepEmail: 'email', WepToDo: 'todo', WepMeeting: 'meeting'}[workEffort.purposeEnumId] || 'task'
}
const grouped = {overdue: [], dueToday: [], laterToday: []}
const items = []
const builtIn = attempt(() => {
    const taskCondition = cf.makeCondition([
        cf.makeCondition('workEffortTypeEnumId', 'equals', 'WetTask'),
        cf.makeCondition('statusId', 'not-in', ['WeComplete', 'WeClosed', 'WeCancelled'], true),
        cf.makeCondition([
            cf.makeCondition('estimatedCompletionDate', 'less', tomorrowStart),
            cf.makeCondition([cf.makeCondition('estimatedCompletionDate', 'is-null', null),
                cf.makeCondition('estimatedStartDate', 'less', tomorrowStart)], 'and')], 'or')], 'and')
    const eventCondition = cf.makeCondition([
        cf.makeCondition('workEffortTypeEnumId', 'equals', 'WetEvent'),
        cf.makeCondition('statusId', 'not-equals', 'WeCancelled', true),
        cf.makeCondition([
            // timed: starts before tomorrow and has not ended; with no end it lasts to the end of its start day
            cf.makeCondition([
                cf.makeCondition('estimatedStartDate', 'less', tomorrowStart),
                cf.makeCondition([
                    cf.makeCondition('estimatedCompletionDate', 'greater', new Date(nowMillis)),
                    cf.makeCondition([cf.makeCondition('estimatedCompletionDate', 'is-null', null),
                        cf.makeCondition('estimatedStartDate', 'greater-equals', todayStart)], 'and')], 'or')], 'and'),
            // all day: today is one of its days
            cf.makeCondition([
                cf.makeCondition('estimatedStartDate', 'is-null', null),
                cf.makeCondition('allDayStart', 'less-equals', todayDate),
                cf.makeCondition([
                    cf.makeCondition('allDayEnd', 'greater-equals', todayDate),
                    cf.makeCondition([cf.makeCondition('allDayEnd', 'is-null', null),
                        cf.makeCondition('allDayStart', 'equals', todayDate)], 'and')], 'or')], 'and')], 'or')], 'and')
    let find = ec.entity.find('mantle.work.effort.WorkEffortAndParty').condition('partyId', partyId)
            .condition(cf.makeConditionDate('fromDate', 'thruDate', now))
            .condition(cf.makeCondition('partyStatusId', 'not-in', ['WeptDeclined', 'WeptUnassigned'], true))
            .condition(cf.makeCondition([taskCondition, eventCondition], 'or'))
    for (const field of ['workEffortId', 'workEffortTypeEnumId', 'purposeEnumId', 'workEffortName', 'statusId', 'priority',
            'ownerPartyId', 'estimatedStartDate', 'estimatedCompletionDate', 'allDayStart', 'allDayEnd', 'roleTypeId',
            'fromDate', 'snoozedThruDate']) find = find.selectField(field)
    // one entry per work effort: the user may have it in several roles; a snooze is on each of the user's rows
    const byId = new Map()
    for (const row of find.list()) {
        let entry = byId.get(row.workEffortId)
        if (!entry) {
            entry = {workEffort: row.getMap(), roles: new Set(), snoozedThru: null}
            byId.set(row.workEffortId, entry)
        }
        entry.roles.add(row.roleTypeId)
        const snoozedThru = toMillis(row.snoozedThruDate)
        if (snoozedThru != null && (entry.snoozedThru == null || snoozedThru > entry.snoozedThru)) entry.snoozedThru = snoozedThru
    }
    for (const entry of byId.values()) {
        if (entry.snoozedThru != null && entry.snoozedThru > nowMillis) continue
        const workEffort = entry.workEffort
        const isEvent = workEffort.workEffortTypeEnumId === 'WetEvent'
        const item = {kind: kindOf(workEffort), workEffortId: workEffort.workEffortId,
            title: workEffort.workEffortName || workEffort.workEffortId, dueDate: null, startDate: null, endDate: null,
            allDay: false, priority: workEffort.priority ?? null, statusId: workEffort.statusId ?? null, assignees: [],
            record: null, canUpdate: !isEvent && (entry.roles.has('Assignee') || workEffort.ownerPartyId === partyId),
            hasCallLink: false, source: null}
        let group
        let at
        if (!isEvent) {
            at = toMillis(workEffort.estimatedCompletionDate) ?? toMillis(workEffort.estimatedStartDate)
            item.dueDate = asDate(at)
            item.startDate = asDate(toMillis(workEffort.estimatedStartDate))
            group = at < todayStartMillis ? 'overdue' : 'dueToday'
        } else if (workEffort.estimatedStartDate != null) {
            at = toMillis(workEffort.estimatedStartDate)
            item.startDate = asDate(at)
            item.endDate = asDate(toMillis(workEffort.estimatedCompletionDate))
            group = at > nowMillis ? 'laterToday' : 'dueToday'
        } else {
            const firstDay = dayTextOf(workEffort.allDayStart)
            at = dayStart(firstDay)
            item.allDay = true
            item.startDate = asDate(at)
            item.endDate = asDate(nextDayStart(dayTextOf(workEffort.allDayEnd) || firstDay) - 1)
            group = 'dueToday'
        }
        grouped[group].push({at: at, item: item})
        items.push(item)
    }
})
if (!builtIn.ok) {
    ec.logger.error(`Today of user ${userId} (party ${partyId}): the tasks and events failed and are left out: ${builtIn.message}`)
    failedSources.push({service: builtInService, label: null, message: builtIn.message})
}
const byDate = (left, right) => (left.at ?? 0) - (right.at ?? 0) || (left.item.priority ?? 99) - (right.item.priority ?? 99) ||
        String(left.item.title).localeCompare(String(right.item.title))
overdue = grouped.overdue.sort(byDate).map((entry) => entry.item)
dueToday = grouped.dueToday.sort(byDate).map((entry) => entry.item)
laterToday = grouped.laterToday.sort(byDate).map((entry) => entry.item)
if (countOnly) return

const workEffortIds = items.map((item) => item.workEffortId)
const partyName = (party) => party ? (party.organizationName || [party.firstName, party.lastName].filter((name) => name).join(' ') ||
        party.pseudoId || party.partyId) : null
// the record of each item: the own joins of get#RecordLinkInfo (RequestWorkEffort, WikiPageWorkEffort), then
// WorkEffortRecord; its name under the user's filters, else its type and id
if (workEffortIds.length) {
    const records = attempt(() => {
        const links = {}
        const addLink = (workEffortId, recordEntityName, recordId) => {
            if (!links[workEffortId]) links[workEffortId] = {recordEntityName: recordEntityName, recordId: recordId}
        }
        for (const row of ec.entity.find('mantle.request.RequestWorkEffort').condition('workEffortId', 'in', workEffortIds).list())
            addLink(row.workEffortId, 'mantle.request.Request', row.requestId)
        for (const row of ec.entity.find('mantle.work.effort.WikiPageWorkEffort').condition('workEffortId', 'in', workEffortIds).list())
            addLink(row.workEffortId, 'moqui.resource.wiki.WikiPage', row.wikiPageId)
        for (const row of ec.entity.find('mantle.work.effort.WorkEffortRecord').condition('workEffortId', 'in', workEffortIds)
                .orderBy('linkedDate').list()) addLink(row.workEffortId, row.recordEntityName, row.recordId)
        const typeNames = {'mantle.order.OrderHeader': 'Order', 'moqui.resource.wiki.WikiPage': 'Page'}
        const nameFields = {'mantle.order.OrderHeader': 'orderName', 'mantle.request.Request': 'requestName',
            'moqui.resource.wiki.WikiPage': 'pagePath', 'mantle.work.effort.WorkEffort': 'workEffortName',
            'mantle.product.Product': 'productName', 'mantle.facility.Facility': 'facilityName',
            'mantle.product.asset.Asset': 'assetName', 'mantle.marketing.contact.ContactList': 'contactListName'}
        const names = {}
        const recordName = (recordEntityName, recordId) => {
            let typeName = typeNames[recordEntityName] || recordEntityName.substring(recordEntityName.lastIndexOf('.') + 1)
            const found = attempt(() => {
                const made = ec.entity.makeValue(recordEntityName)
                if (!typeNames[recordEntityName]) typeName = made.getEntityNamePretty()
                if (recordEntityName === 'mantle.party.Party') {
                    // someone else's personal contact is not named
                    const party = ec.entity.find('mantle.party.PartyDetail').condition('partyId', recordId).one()
                    return party && !(party.privateOwnerUserId && party.privateOwnerUserId !== ec.user.userId) ? partyName(party) : null
                }
                const nameField = nameFields[recordEntityName]
                if (!nameField) return null
                const keyField = Object.keys(made.getPrimaryKeys())[0]
                return ec.entity.find(recordEntityName).condition(keyField, recordId).one()?.[nameField] || null
            })
            if (recordEntityName === 'mantle.party.Party') return found.ok && found.out ? found.out : `${typeName} ${recordId}`
            return found.ok && found.out ? `${typeName} ${recordId} · ${found.out}` : `${typeName} ${recordId}`
        }
        for (const item of items) {
            const link = links[item.workEffortId]
            if (!link) continue
            const key = `${link.recordEntityName}|${link.recordId}`
            if (!(key in names)) names[key] = recordName(link.recordEntityName, link.recordId)
            item.record = {recordEntityName: link.recordEntityName, recordId: link.recordId, recordName: names[key]}
        }
    })
    if (!records.ok) ec.logger.error(`Today of user ${userId}: the records of the items failed and are left out: ${records.message}`)

    const assignees = attempt(() => {
        const byWorkEffort = {}
        const partyIds = new Set()
        for (const row of ec.entity.find('mantle.work.effort.WorkEffortParty').condition('workEffortId', 'in', workEffortIds)
                .condition('roleTypeId', 'Assignee').condition('partyId', 'not-equals', partyId)
                .condition(cf.makeConditionDate('fromDate', 'thruDate', now))
                .condition(cf.makeCondition('statusId', 'not-in', ['WeptDeclined', 'WeptUnassigned'], true)).list()) {
            const list = byWorkEffort[row.workEffortId] || (byWorkEffort[row.workEffortId] = [])
            if (!list.includes(row.partyId)) list.push(row.partyId)
            partyIds.add(row.partyId)
        }
        if (partyIds.size === 0) return
        const names = {}
        for (const party of ec.entity.find('mantle.party.PartyDetail').condition('partyId', 'in', Array.from(partyIds)).list()) {
            names[party.partyId] = party.privateOwnerUserId && party.privateOwnerUserId !== ec.user.userId ? party.partyId : partyName(party)
        }
        for (const item of items) {
            const ids = byWorkEffort[item.workEffortId]
            if (ids) item.assignees = ids.map((id) => ({partyId: id, name: names[id] || id}))
                    .sort((left, right) => String(left.name).localeCompare(String(right.name)))
        }
    })
    if (!assignees.ok) ec.logger.error(`Today of user ${userId}: the assignees of the items failed and are left out: ${assignees.message}`)
}

// the today-source providers, each in a transaction of its own
const sourceEntries = sourceServiceNames == null ? [] : (typeof sourceServiceNames === 'string' ?
        sourceServiceNames.split(',') : Array.from(sourceServiceNames))
for (const entry of sourceEntries) {
    const service = String((entry && typeof entry === 'object' ? entry.service : entry) || '').trim()
    let label = entry && typeof entry === 'object' && entry.label ? String(entry.label) : null
    if (!service) continue
    const fail = (message) => {
        ec.logger.error(`Today of user ${userId}: the source ${service}${label ? ' (' + label + ')' : ''} failed and is left out: ${message}`)
        failedSources.push({service: service, label: label, message: message})
    }
    const verb = service.substring(service.lastIndexOf('.') + 1).split('#')[0]
    if (!['get', 'find'].includes(verb)) { fail('A today source must be a get or find service'); continue }
    const called = attempt(() => ec.service.sync().name(service).parameters({userId: userId, partyId: partyId,
            fromDate: todayStart, thruDate: tomorrowStart}).requireNewTransaction(true).call())
    if (!called.ok) { fail(called.message); continue }
    const sourceItems = called.out?.items
    if (sourceItems == null || typeof sourceItems !== 'object' || typeof sourceItems.length !== 'number') {
        fail('The source answered no items list')
        continue
    }
    if (!label) label = called.out.label ? String(called.out.label) : service
    const groupItems = []
    for (const sourceItem of Array.from(sourceItems)) {
        if (sourceItem == null || typeof sourceItem !== 'object') continue
        groupItems.push(Object.assign({kind: 'task', workEffortId: null, title: null, dueDate: null, startDate: null,
            endDate: null, allDay: false, priority: null, statusId: null, assignees: [], record: null, canUpdate: false,
            hasCallLink: false}, sourceItem, {source: label}))
    }
    sourceGroups.push({label: label, service: service, items: groupItems})
}

if (userId) {
    const approvals = attempt(() => ec.service.sync().name('mantle.party.PartyServices.count#UserNotifications')
            .parameters({userId: userId}).call())
    if (approvals.ok) approvalCount = approvals.out?.approvalCount ?? 0
    else ec.logger.error(`Today of user ${userId}: the approvals count failed: ${approvals.message}`)
}

updatedCount = 0
const cf = ec.entity.conditionFactory
const partyId = ec.user.userAccount?.partyId
if (!partyId) { ec.message.addError('Snoozing an item needs a user with a party'); return }
const toMillis = (value) => {
    if (value == null || value === '') return null
    if (typeof value === 'number') return value
    if (value instanceof Date) return value.getTime()
    const text = String(value)
    return /^-?\d+$/.test(text) ? Number(text) : Date.parse(text)
}
const rows = Array.from(ec.entity.find('mantle.work.effort.WorkEffortParty').condition('workEffortId', workEffortId)
        .condition('partyId', partyId).condition(cf.makeConditionDate('fromDate', 'thruDate', ec.user.nowTimestamp)).list())
if (rows.length === 0) { ec.message.addError(`You are not on ${workEffortId}, so it is not on your Today`); return }
let thruMillis = null
if (!unsnooze) {
    thruMillis = toMillis(snoozedThruDate)
    if (thruMillis == null) {
        // tomorrow 09:00 in the session's time zone; a day is 23 to 25 hours long
        const pattern = 'yyyy-MM-dd HH:mm:ss.SSS'
        const todayText = ec.l10n.format(ec.user.nowTimestamp, 'yyyy-MM-dd')
        const todayStart = toMillis(ec.l10n.parseTimestamp(todayText + ' 00:00:00.000', pattern))
        const tomorrowText = ec.l10n.format(String(todayStart + 30 * 3600000), 'yyyy-MM-dd')
        thruMillis = toMillis(ec.l10n.parseTimestamp(tomorrowText + ' 09:00:00.000', pattern))
    }
}
snoozedThruDate = thruMillis == null ? null : new Date(thruMillis)
for (const row of rows) {
    row.snoozedThruDate = snoozedThruDate
    row.update()
    updatedCount++
}

if.script:
// timestamps reach a script as epoch millis text; whole minutes add the same in any time zone
const convertedAmount = convertDurOut.convertedAmount
const durationMinutes = (convertedAmount == null || toDecimal(convertedAmount).isZero()) ? 60 : Math.trunc(toDecimal(convertedAmount).toNumber())
const startMillis = /^-?\d+$/.test(String(startDate)) ? Number(startDate) : Date.parse(String(startDate))
endDate = String(startMillis + durationMinutes * 60000)
